const HAPPINESS_200 = [{"id": "happiness-001", "name": "Аня", "text": "Ооо, свежая футболка после душа! Уже хорошо.", "cat": "Повседневные радости"}, {"id": "happiness-002", "name": "Костя", "text": "Сегодня проснулся раньше будильника, глянул на часы — ещё целый час сна! Я счастлив 😂", "cat": "Повседневные радости"}, {"id": "happiness-003", "name": "Лера", "text": "Сегодня пила кофе у окна и вдруг заметила, как красиво солнце легло на подоконник. Вот прям остановилась.", "cat": "Повседневные радости"}, {"id": "happiness-004", "name": "Паша", "text": "Наточил нож. Помидор режется идеально. Всё, день удался.", "cat": "Повседневные радости"}, {"id": "happiness-005", "name": "Маша", "text": "Когда дома пахнет свежим хлебом, мне кажется, что весь мир на минуту становится добрее.", "cat": "Повседневные радости"}, {"id": "happiness-006", "name": "Сева", "text": "Кайфую, когда наушники с первого раза подключились к нужному устройству. Редкая, но мощная радость 😄", "cat": "Повседневные радости"}, {"id": "happiness-007", "name": "Нина", "text": "Счастлива, когда нахожу в кармане куртки забытую конфету. Привет от меня из прошлого!", "cat": "Повседневные радости"}, {"id": "happiness-008", "name": "Артём", "text": "Обожаю вечер после хорошо сделанного дела: ноги устали, зато в голове тихо.", "cat": "Повседневные радости"}, {"id": "happiness-009", "name": "Даша", "text": "Меня радует, когда кот выбирает спать именно рядом со мной. Считаю это официальным признанием заслуг.", "cat": "Повседневные радости"}, {"id": "happiness-010", "name": "Илья", "text": "Кайфую от дороги домой, когда все дела уже позади и можно просто слушать музыку.", "cat": "Повседневные радости"}, {"id": "happiness-011", "name": "Катя", "text": "Люблю рисовать на запотевшем зеркале смешные рожицы. Да, мне не пять лет, и что? 😁", "cat": "Повседневные радости"}, {"id": "happiness-012", "name": "Рома", "text": "Самая приятная мелочь — сесть в машину после мойки. Даже едет как будто лучше.", "cat": "Повседневные радости"}, {"id": "happiness-013", "name": "Соня", "text": "Я счастлива, когда утро начинается без спешки и можно допить чай, пока он ещё горячий.", "cat": "Повседневные радости"}, {"id": "happiness-014", "name": "Макс", "text": "Обожаю момент, когда находишь идеальную громкость музыки: и слышно всё, и уши целы.", "cat": "Повседневные радости"}, {"id": "happiness-015", "name": "Юля", "text": "Радуюсь, когда постельное бельё только сменили. Особенно если подушка прохладная.", "cat": "Повседневные радости"}, {"id": "happiness-016", "name": "Вика", "text": "Люблю выбирать фрукты на рынке и вдруг найти невероятно сладкий персик.", "cat": "Повседневные радости"}, {"id": "happiness-017", "name": "Гриша", "text": "Кайф — когда пакет с продуктами донёс до дома, и ни одна ручка не порвалась. Сегодня я победитель.", "cat": "Повседневные радости"}, {"id": "happiness-018", "name": "Женя", "text": "Завтра выходной! Аааа 😌", "cat": "Повседневные радости"}, {"id": "happiness-019", "name": "Таня", "text": "Собрала ужин из остатков. Получилось так вкусно, что теперь не знаю, как повторить рецепт 😅", "cat": "Повседневные радости"}, {"id": "happiness-020", "name": "Денис", "text": "Люблю момент, когда открываешь окно после уборки и в комнате пахнет свежестью.", "cat": "Повседневные радости"}, {"id": "happiness-021", "name": "Аня", "text": "Мне так нравится пить воду после долгой прогулки. Простая вещь, а удовольствие настоящее.", "cat": "Повседневные радости"}, {"id": "happiness-022", "name": "Костя", "text": "Когда лифт уже стоит на моём этаже — чувствую себя человеком, которому сегодня везёт по-крупному.", "cat": "Повседневные радости"}, {"id": "happiness-023", "name": "Лера", "text": "Счастлива, когда на кухне тихо, за окном темнеет, а лампа светит таким мягким жёлтым светом.", "cat": "Повседневные радости"}, {"id": "happiness-024", "name": "Паша", "text": "Кайфую, когда нужный болт нашёлся именно в той коробке, где я его искал.", "cat": "Повседневные радости"}, {"id": "happiness-025", "name": "Маша", "text": "Люблю запах апельсина, который кто-то начал чистить в соседней комнате.", "cat": "Повседневные радости"}, {"id": "happiness-026", "name": "Сева", "text": "Радуюсь, когда компьютер не предлагает обновиться именно в тот момент, когда я тороплюсь.", "cat": "Повседневные радости"}, {"id": "happiness-027", "name": "Нина", "text": "Мне нравится раскладывать выстиранные полотенца стопочкой. Не знаю почему, но на душе порядок.", "cat": "Повседневные радости"}, {"id": "happiness-028", "name": "Артём", "text": "Счастлив, когда в конце дня видно результат работы, а не только список того, что ещё предстоит.", "cat": "Повседневные радости"}, {"id": "happiness-029", "name": "Даша", "text": "Кайфую, когда собака встречает меня так, будто я вернулась из кругосветного путешествия, хотя отходила за хлебом.", "cat": "Повседневные радости"}, {"id": "happiness-030", "name": "Илья", "text": "Люблю случайно попасть в пустой автобус и выбрать место у окна.", "cat": "Повседневные радости"}, {"id": "happiness-031", "name": "Катя", "text": "Сегодня смешала две краски и получила тот самый оттенок, который искала. Сижу, любуюсь, будто совершила научное открытие. А ведь просто нарисовала небо.", "cat": "Повседневные радости"}, {"id": "happiness-032", "name": "Рома", "text": "Обожаю звук, с которым закрывается добротная дверь. Вот прям приятно.", "cat": "Повседневные радости"}, {"id": "happiness-033", "name": "Соня", "text": "Счастлива, когда удаётся почитать хотя бы десять страниц без уведомлений и суеты.", "cat": "Повседневные радости"}, {"id": "happiness-034", "name": "Макс", "text": "Кайф — сделать глоток холодной воды после тренировки и почувствовать, что оживаешь.", "cat": "Повседневные радости"}, {"id": "happiness-035", "name": "Юля", "text": "Люблю, когда дети уснули, посуда вымыта и дома наконец-то слышно, как тикают часы.", "cat": "Повседневные радости"}, {"id": "happiness-036", "name": "Вика", "text": "Меня радуют чистые окна. Сразу кажется, что свет дома стал другим.", "cat": "Повседневные радости"}, {"id": "happiness-037", "name": "Гриша", "text": "Счастье — когда открыл банку с первого раза без танцев с полотенцем и горячей водой 😂", "cat": "Повседневные радости"}, {"id": "happiness-038", "name": "Женя", "text": "Люблю, когда утренний тост получился именно золотистый, а не «ой».", "cat": "Повседневные радости"}, {"id": "happiness-039", "name": "Таня", "text": "Я радуюсь, когда на улице прохладно и можно наконец надеть любимую толстовку.", "cat": "Повседневные радости"}, {"id": "happiness-040", "name": "Денис", "text": "Кайфую, когда вечером снимаю рабочую обувь. Ради такого момента стоило пройти весь день.", "cat": "Повседневные радости"}, {"id": "happiness-041", "name": "Аня", "text": "Обожаю, когда чай заварился именно так, как люблю: крепко, но без горечи.", "cat": "Повседневные радости"}, {"id": "happiness-042", "name": "Костя", "text": "Мне нравится находить свободную розетку возле дивана. Современное бытовое счастье.", "cat": "Повседневные радости"}, {"id": "happiness-043", "name": "Лера", "text": "Радуюсь, когда случайно замечаю красивую тень от растения на стене.", "cat": "Повседневные радости"}, {"id": "happiness-044", "name": "Паша", "text": "Счастлив, когда что-то починил и оно снова работает без всяких «ну пока держится».", "cat": "Повседневные радости"}, {"id": "happiness-045", "name": "Маша", "text": "Люблю тихие воскресные утра, когда город будто говорит шёпотом.", "cat": "Повседневные радости"}, {"id": "happiness-046", "name": "Сева", "text": "Кайфую от идеально чистого рабочего стола на компьютере. Держится, правда, минут сорок.", "cat": "Повседневные радости"}, {"id": "happiness-047", "name": "Нина", "text": "Счастлива, когда засыпаю под чистым пледом, который пахнет солнцем.", "cat": "Повседневные радости"}, {"id": "happiness-048", "name": "Артём", "text": "Люблю первый глоток горячего супа после дня на холоде. Никакого ресторана не надо.", "cat": "Повседневные радости"}, {"id": "happiness-049", "name": "Даша", "text": "Меня радует, когда питомец во сне смешно дёргает лапами. Интересно, кого там догоняет?", "cat": "Повседневные радости"}, {"id": "happiness-050", "name": "Илья", "text": "Счастье — идти домой с вкусным пакетом из пекарни и не съесть всё по дороге.", "cat": "Повседневные радости"}, {"id": "happiness-051", "name": "Юля", "text": "Сегодня за общим столом все вдруг начали хохотать над какой-то глупостью. Уже никто не помнил, из-за чего начали, но остановиться было невозможно. Обожаю такие вечера.", "cat": "Близкие люди и общение"}, {"id": "happiness-052", "name": "Аня", "text": "Люблю, когда мама звонит просто спросить, как дела, и разговор неожиданно затягивается на час.", "cat": "Близкие люди и общение"}, {"id": "happiness-053", "name": "Рома", "text": "Кайфую, когда друг понимает шутку ещё до того, как я её договорил.", "cat": "Близкие люди и общение"}, {"id": "happiness-054", "name": "Лера", "text": "Мне очень тепло от сообщений «доехала?» — там столько заботы в одном слове.", "cat": "Близкие люди и общение"}, {"id": "happiness-055", "name": "Гриша", "text": "Счастлив, когда мы с отцом что-нибудь мастерим вместе и почти не разговариваем. И так всё понятно.", "cat": "Близкие люди и общение"}, {"id": "happiness-056", "name": "Маша", "text": "Люблю, когда кто-то помнит маленькую деталь, которую я рассказала давным-давно.", "cat": "Близкие люди и общение"}, {"id": "happiness-057", "name": "Костя", "text": "Обожаю, когда друг приходит «на пять минут», а мы в итоге три часа пьём чай и обсуждаем жизнь.", "cat": "Близкие люди и общение"}, {"id": "happiness-058", "name": "Соня", "text": "Я рада, когда близкий человек может просто посидеть рядом молча, и неловкости нет.", "cat": "Близкие люди и общение"}, {"id": "happiness-059", "name": "Макс", "text": "Кайфую от совместных поездок, когда половину дороги мы поём песни громче магнитолы.", "cat": "Близкие люди и общение"}, {"id": "happiness-060", "name": "Вика", "text": "Счастлива, когда племянница показывает мне свой рисунок и ждёт мою реакцию, как будто это музейная премьера.", "cat": "Близкие люди и общение"}, {"id": "happiness-061", "name": "Паша", "text": "Люблю, когда сосед придержал дверь, а ты успел сказать ему нормальное человеческое спасибо.", "cat": "Близкие люди и общение"}, {"id": "happiness-062", "name": "Катя", "text": "Меня радует, когда удаётся сделать человеку неожиданный, но очень подходящий подарок.", "cat": "Близкие люди и общение"}, {"id": "happiness-063", "name": "Илья", "text": "Вчера случайно встретил школьного друга. Мы не виделись сто лет, но через пять минут уже смеялись над теми же историями, что и раньше. Такое чувство, будто время на секунду остановилось.", "cat": "Близкие люди и общение"}, {"id": "happiness-064", "name": "Нина", "text": "Люблю слушать семейные истории, которые старшие рассказывают в сотый раз. Каждый раз замечаю новое.", "cat": "Близкие люди и общение"}, {"id": "happiness-065", "name": "Денис", "text": "Мне хорошо, когда можно честно сказать другу «день был тяжёлый» и не придумывать бодрый голос.", "cat": "Близкие люди и общение"}, {"id": "happiness-066", "name": "Таня", "text": "Счастлива, когда за ужином все убирают телефоны и действительно разговаривают.", "cat": "Близкие люди и общение"}, {"id": "happiness-067", "name": "Женя", "text": "Люблю, когда кто-то смеётся над моей нелепой шуткой. Даже если смеётся только один человек.", "cat": "Близкие люди и общение"}, {"id": "happiness-068", "name": "Сева", "text": "Кайфую, когда в общем чате вдруг собираются все старые друзья, даже те, кто годами молчит.", "cat": "Близкие люди и общение"}, {"id": "happiness-069", "name": "Даша", "text": "Радуюсь, когда ребёнок протягивает мне найденный красивый камешек как сокровище.", "cat": "Близкие люди и общение"}, {"id": "happiness-070", "name": "Артём", "text": "Счастлив, когда моя помощь оказалась к месту и человеку стало заметно легче.", "cat": "Близкие люди и общение"}, {"id": "happiness-071", "name": "Юля", "text": "Люблю, когда близкие приезжают в гости без особой программы: просто быть вместе.", "cat": "Близкие люди и общение"}, {"id": "happiness-072", "name": "Аня", "text": "Меня греет, когда любимый человек помнит, какой чай я пью, и сам его заваривает.", "cat": "Близкие люди и общение"}, {"id": "happiness-073", "name": "Рома", "text": "Кайф — обнять друга после долгой разлуки и не знать, что сказать первым.", "cat": "Близкие люди и общение"}, {"id": "happiness-074", "name": "Лера", "text": "Счастлива, когда мы с подругой можем смеяться над историей, которую никто другой не поймёт.", "cat": "Близкие люди и общение"}, {"id": "happiness-075", "name": "Гриша", "text": "Люблю, когда сын просит показать, как что-то устроено. Сразу хочется стать лучшим объясняльщиком в мире.", "cat": "Близкие люди и общение"}, {"id": "happiness-076", "name": "Маша", "text": "Мне нравится, когда кто-то искренне радуется за меня, без сравнения и соревнования.", "cat": "Близкие люди и общение"}, {"id": "happiness-077", "name": "Костя", "text": "Кайфую, когда можно позвонить человеку без повода, и он говорит: «О, я как раз о тебе думал!»", "cat": "Близкие люди и общение"}, {"id": "happiness-078", "name": "Соня", "text": "Счастлива от маленьких семейных ритуалов: одно и то же пожелание на ночь, знакомая чашка на столе.", "cat": "Близкие люди и общение"}, {"id": "happiness-079", "name": "Макс", "text": "Люблю, когда мы играем в настолку и все спорят о правилах, но потом ещё неделю вспоминают вечер.", "cat": "Близкие люди и общение"}, {"id": "happiness-080", "name": "Вика", "text": "Радуюсь, когда бабушка рассказывает, каким смешным был папа в детстве.", "cat": "Близкие люди и общение"}, {"id": "happiness-081", "name": "Паша", "text": "Счастлив, когда встречаю мастера, который не жадничает поделиться своим опытом.", "cat": "Близкие люди и общение"}, {"id": "happiness-082", "name": "Катя", "text": "Люблю писать открытки от руки. Особенно представлять, как человек откроет конверт.", "cat": "Близкие люди и общение"}, {"id": "happiness-083", "name": "Илья", "text": "Кайфую от разговора в дороге с незнакомым человеком, когда выходишь на своей остановке с улыбкой.", "cat": "Близкие люди и общение"}, {"id": "happiness-084", "name": "Нина", "text": "Счастлива, когда кто-то замечает, что я устала, и просто предлагает передохнуть.", "cat": "Близкие люди и общение"}, {"id": "happiness-085", "name": "Денис", "text": "Семейные завтраки без спешки — моя любовь.", "cat": "Близкие люди и общение"}, {"id": "happiness-086", "name": "Таня", "text": "Меня радует, когда после ссоры мы всё-таки находим слова, чтобы помириться.", "cat": "Близкие люди и общение"}, {"id": "happiness-087", "name": "Женя", "text": "Кайф — увидеть, как человек впервые пробует блюдо, которое я приготовил, и улыбается.", "cat": "Близкие люди и общение"}, {"id": "happiness-088", "name": "Сева", "text": "Счастлив, когда у нас с друзьями получается общее дело, которое по отдельности никто бы не осилил.", "cat": "Близкие люди и общение"}, {"id": "happiness-089", "name": "Даша", "text": "Люблю, когда мой человек присылает фото какой-нибудь ерунды с подписью «это напомнило о тебе».", "cat": "Близкие люди и общение"}, {"id": "happiness-090", "name": "Артём", "text": "Радуюсь, когда можно быть собой и не искать правильные слова для каждого предложения.", "cat": "Близкие люди и общение"}, {"id": "happiness-091", "name": "Илья", "text": "Обожаю ранние поезда. За окном туман, кто-то пьёт чай из бумажного стаканчика, вагон ещё сонный. И ты смотришь в окно с приятным чувством: впереди целый день, и пока никто не знает, каким он будет.", "cat": "Природа, путешествия, места"}, {"id": "happiness-092", "name": "Маша", "text": "После дождя листья блестят. И как тут не радоваться?", "cat": "Природа, путешествия, места"}, {"id": "happiness-093", "name": "Нина", "text": "Люблю стоять у моря в ветреную погоду и слушать, как волны перекатывают камни.", "cat": "Природа, путешествия, места"}, {"id": "happiness-094", "name": "Макс", "text": "Кайфую, когда после долгого подъёма наконец открывается вид с вершины. Даже говорить не хочется.", "cat": "Природа, путешествия, места"}, {"id": "happiness-095", "name": "Вика", "text": "Меня радует первый снег, пока его ещё никто не успел превратить в серую кашу.", "cat": "Природа, путешествия, места"}, {"id": "happiness-096", "name": "Рома", "text": "Счастлив, когда еду по пустой загородной дороге, а по сторонам поля до горизонта.", "cat": "Природа, путешествия, места"}, {"id": "happiness-097", "name": "Лера", "text": "Обожаю запах земли после летнего ливня. Иногда специально выхожу на балкон вдохнуть.", "cat": "Природа, путешествия, места"}, {"id": "happiness-098", "name": "Гриша", "text": "Люблю посидеть у костра и смотреть, как огонь сам придумывает себе танец.", "cat": "Природа, путешествия, места"}, {"id": "happiness-099", "name": "Аня", "text": "Счастлива, когда в парке вижу, как сквозь кроны деревьев пробивается вечернее солнце.", "cat": "Природа, путешествия, места"}, {"id": "happiness-100", "name": "Паша", "text": "Кайфую от похода, где телефон почти не ловит, зато отлично слышно птиц.", "cat": "Природа, путешествия, места"}, {"id": "happiness-101", "name": "Катя", "text": "Меня вдохновляют маленькие незнакомые улочки, где за каждым поворотом что-то красивое.", "cat": "Природа, путешествия, места"}, {"id": "happiness-102", "name": "Денис", "text": "Люблю осенний лес: под ногами шуршит, воздух холодный, а идти совсем не хочется быстрее.", "cat": "Природа, путешествия, места"}, {"id": "happiness-103", "name": "Таня", "text": "Счастлива, когда нахожу в городе цветущий дворик, о котором раньше даже не знала.", "cat": "Природа, путешествия, места"}, {"id": "happiness-104", "name": "Женя", "text": "Кайфую, когда летом можно выйти босиком на траву и никуда не спешить.", "cat": "Природа, путешествия, места"}, {"id": "happiness-105", "name": "Соня", "text": "Люблю смотреть на облака и придумывать, на что они похожи. Это мой бесплатный кинотеатр.", "cat": "Природа, путешествия, места"}, {"id": "happiness-106", "name": "Костя", "text": "Счастье — найти на пляже камень, идеально подходящий для того, чтобы пустить «блинчик».", "cat": "Природа, путешествия, места"}, {"id": "happiness-107", "name": "Юля", "text": "Обожаю, когда дети впервые за сезон видят снег и бегут к окну как на праздник.", "cat": "Природа, путешествия, места"}, {"id": "happiness-108", "name": "Сева", "text": "Радуюсь чистому звёздному небу вдали от города. Сразу чувствуешь масштаб происходящего.", "cat": "Природа, путешествия, места"}, {"id": "happiness-109", "name": "Даша", "text": "Кайфую, когда на прогулке вдруг встречаю ёжика. Всю дорогу потом рассказываю, кого видела.", "cat": "Природа, путешествия, места"}, {"id": "happiness-110", "name": "Артём", "text": "Люблю сидеть у реки и смотреть, как вода уносит маленькие листья.", "cat": "Природа, путешествия, места"}, {"id": "happiness-111", "name": "Илья", "text": "Счастлив, когда приезжаю в новое место и первым делом иду пешком без строгого маршрута.", "cat": "Природа, путешествия, места"}, {"id": "happiness-112", "name": "Маша", "text": "Обожаю свет в комнате во время летней грозы: на секунду всё становится серебряным.", "cat": "Природа, путешествия, места"}, {"id": "happiness-113", "name": "Нина", "text": "Мне нравится запах сосен в жаркий день. От него сразу вспоминаются каникулы.", "cat": "Природа, путешествия, места"}, {"id": "happiness-114", "name": "Макс", "text": "Кайфую от холодного воздуха на лице после того, как вышел из тёплого помещения зимой.", "cat": "Природа, путешествия, места"}, {"id": "happiness-115", "name": "Вика", "text": "Счастлива, когда весной вдруг слышу птиц по утрам и понимаю: ну всё, дождались.", "cat": "Природа, путешествия, места"}, {"id": "happiness-116", "name": "Рома", "text": "Люблю останавливаться у красивого вида во время поездки, даже если это добавляет полчаса к дороге.", "cat": "Природа, путешествия, места"}, {"id": "happiness-117", "name": "Лера", "text": "Радуюсь, когда замечаю маленький цветок, пробившийся между плитками тротуара.", "cat": "Природа, путешествия, места"}, {"id": "happiness-118", "name": "Гриша", "text": "Кайфую от рыбалки даже без улова. Сидишь у воды, слушаешь тишину — уже хорошо.", "cat": "Природа, путешествия, места"}, {"id": "happiness-119", "name": "Аня", "text": "Счастлива, когда вечерний город отражается в лужах, как ещё один перевёрнутый город.", "cat": "Природа, путешествия, места"}, {"id": "happiness-120", "name": "Паша", "text": "Люблю утренний воздух на даче, когда ещё прохладно и всё вокруг только просыпается.", "cat": "Природа, путешествия, места"}, {"id": "happiness-121", "name": "Артём", "text": "Три дня не мог понять, как подступиться к задаче. А сегодня во время прогулки вдруг всё сошлось! Пришёл домой и сразу записал, пока не убежало. Вот ради таких моментов люблю свою работу.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-122", "name": "Катя", "text": "Счастлива, когда рисую что-то просто для себя, без оценки и ожиданий.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-123", "name": "Паша", "text": "Обожаю собрать мебель и обнаружить, что ни одной лишней детали не осталось. Вот это триумф!", "cat": "Достижения, работа, творчество"}, {"id": "happiness-124", "name": "Сева", "text": "Люблю момент, когда код заработал после часа поисков ошибки. Особенно если ошибка была в одной букве 🙈", "cat": "Достижения, работа, творчество"}, {"id": "happiness-125", "name": "Таня", "text": "Радуюсь, когда новое блюдо получается с первого раза и кто-то просит рецепт.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-126", "name": "Макс", "text": "Кайфую, когда получается движение, которое неделю не давалось на тренировках.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-127", "name": "Денис", "text": "Счастлив, когда клиент говорит: «Вот именно это я и хотел», а я понимаю, что мы друг друга услышали.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-128", "name": "Вика", "text": "Люблю, когда удаётся закончить книгу и ещё долго ходишь с её миром в голове.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-129", "name": "Рома", "text": "Кайфую от поездки на велосипеде после того, как сам его настроил. Всё крутится без скрипа!", "cat": "Достижения, работа, творчество"}, {"id": "happiness-130", "name": "Лера", "text": "Счастлива, когда смогла сказать «нет» лишней задаче и оставить время на важное.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-131", "name": "Маша", "text": "Обожаю найти точные слова для мысли, которую давно не могла выразить.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-132", "name": "Гриша", "text": "Люблю, когда ученик вдруг говорит: «А, так вот как это работает!» Ради такого стоит объяснять.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-133", "name": "Юля", "text": "Радуюсь, когда удалось организовать семейную поездку и все довольны, даже без идеального плана.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-134", "name": "Аня", "text": "Счастлива, когда навела порядок в одном уголке дома и теперь хочется туда смотреть.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-135", "name": "Илья", "text": "Кайфую, когда выучил пару фраз на новом языке и смог применить их в настоящем разговоре.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-136", "name": "Костя", "text": "Люблю забить гол в дружеской игре. Даже если потом пять минут надо отдышаться.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-137", "name": "Соня", "text": "Счастлива, когда наконец дочитываю книгу, которую всё время откладывала, и хочется обсудить её с кем-то.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-138", "name": "Женя", "text": "Радуюсь, когда удаётся сделать красивую фотографию без десятка попыток.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-139", "name": "Нина", "text": "Люблю, когда мои комнатные растения выпускают новый лист. Значит, мы с ними на правильном пути.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-140", "name": "Даша", "text": "Кайфую, когда удаётся научить собаку новой команде. Мы оба такие гордые потом.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-141", "name": "Артём", "text": "Счастлив, когда сделал не всё на свете, а именно то одно, что сегодня было важнее всего.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-142", "name": "Катя", "text": "Меня радует, когда идея из блокнота превращается в настоящую вещь, которую можно потрогать.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-143", "name": "Паша", "text": "После ремонта нажал на выключатель — работает! Ура.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-144", "name": "Сева", "text": "Кайфую, когда объяснил сложную штуку простыми словами и меня поняли.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-145", "name": "Таня", "text": "Счастлива, когда могу позволить себе выходной без чувства, что обязана всё время быть полезной.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-146", "name": "Макс", "text": "Радуюсь, когда после долгого перерыва возвращаюсь к любимому хобби и руки всё помнят.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-147", "name": "Денис", "text": "Люблю сдать работу вовремя и спокойно закрыть ноутбук, не доделывая ночью.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-148", "name": "Вика", "text": "Счастлива, когда нахожу смелость попробовать новое, даже если получается пока криво.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-149", "name": "Рома", "text": "Кайфую от маленьких улучшений: вчера не умел, сегодня уже хоть чуть-чуть получается.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-150", "name": "Лера", "text": "Люблю, когда отмечаю выполненное в списке и понимаю, что день не зря прожит, даже если список не закончился.", "cat": "Достижения, работа, творчество"}, {"id": "happiness-151", "name": "Костя", "text": "Чихнул всего один раз. Рекорд дня 😂", "cat": "Необычное и смешное"}, {"id": "happiness-152", "name": "Гриша", "text": "Кайфую, когда носок из стирки нашёл свою пару. Хоть одна история любви закончилась хорошо.", "cat": "Необычное и смешное"}, {"id": "happiness-153", "name": "Даша", "text": "Радуюсь, когда кот делает вид, что не слышит, но на слово «корм» телепортируется через всю квартиру.", "cat": "Необычное и смешное"}, {"id": "happiness-154", "name": "Сева", "text": "Счастье — когда пароль подошёл с первой попытки и не пришлось вспоминать всю биографию.", "cat": "Необычное и смешное"}, {"id": "happiness-155", "name": "Женя", "text": "Люблю, когда шаурма держит форму до последнего укуса. Уважаю инженерную мысль повара.", "cat": "Необычное и смешное"}, {"id": "happiness-156", "name": "Рома", "text": "Кайфую, когда попал ключом в замок сразу, не устраивая ночной концерт у двери.", "cat": "Необычное и смешное"}, {"id": "happiness-157", "name": "Катя", "text": "Счастлива, когда вижу собаку в смешной одежде и она выглядит довольнее всех прохожих.", "cat": "Необычное и смешное"}, {"id": "happiness-158", "name": "Паша", "text": "Обожаю открыть ящик с инструментами и сразу найти нужную отвёртку. Бывает редко, зато праздник.", "cat": "Необычное и смешное"}, {"id": "happiness-159", "name": "Юля", "text": "Радуюсь, когда дети сами предлагают лечь спать. Обычно это значит, что я сплю и вижу сон 😅", "cat": "Необычное и смешное"}, {"id": "happiness-160", "name": "Илья", "text": "Навигатор впервые привёл меня к двери, а не к забору. Праздник!", "cat": "Необычное и смешное"}, {"id": "happiness-161", "name": "Макс", "text": "Я счастлив, когда мяч попадает точно в корзину для белья. NBA, я на связи.", "cat": "Необычное и смешное"}, {"id": "happiness-162", "name": "Таня", "text": "Люблю, когда купила авокадо и оно оказалось спелым не через три минуты после того, как испортилось.", "cat": "Необычное и смешное"}, {"id": "happiness-163", "name": "Аня", "text": "Радуюсь, когда баночка открылась без помощи сильного человека и семейного совета.", "cat": "Необычное и смешное"}, {"id": "happiness-164", "name": "Соня", "text": "Кайфую, когда поняла шутку через пять минут и всё равно смешно. У меня отложенная доставка юмора.", "cat": "Необычное и смешное"}, {"id": "happiness-165", "name": "Нина", "text": "Счастье — успеть подхватить падающую ложку. Чувствую себя героиней боевика на кухне.", "cat": "Необычное и смешное"}, {"id": "happiness-166", "name": "Костя", "text": "Обожаю, когда курьер приехал точно в тот момент, когда я уже одет, но ещё не ушёл.", "cat": "Необычное и смешное"}, {"id": "happiness-167", "name": "Гриша", "text": "Радуюсь, когда бумажная наклейка снимается с банки целиком, без археологических раскопок.", "cat": "Необычное и смешное"}, {"id": "happiness-168", "name": "Даша", "text": "Люблю, когда пес приносит мне палку размером с самого себя. Масштаб амбиций восхищает.", "cat": "Необычное и смешное"}, {"id": "happiness-169", "name": "Сева", "text": "Счастлив, когда интернет внезапно заработал после того, как я просто посмотрел на роутер строго.", "cat": "Необычное и смешное"}, {"id": "happiness-170", "name": "Женя", "text": "Кайфую, когда блины сами переворачиваются красиво. Ну почти сами, я там немного участвовал.", "cat": "Необычное и смешное"}, {"id": "happiness-171", "name": "Рома", "text": "Обожаю удачно припарковаться с первого раза и сделать вид, будто всегда так умею.", "cat": "Необычное и смешное"}, {"id": "happiness-172", "name": "Катя", "text": "Радуюсь, когда надела носки с разными рисунками и никто не заметил. Тайная вечеринка на ногах.", "cat": "Необычное и смешное"}, {"id": "happiness-173", "name": "Паша", "text": "Счастье — когда скотч легко отрывается от рулона, а не приходится искать край под микроскопом.", "cat": "Необычное и смешное"}, {"id": "happiness-174", "name": "Юля", "text": "Кайфую, когда в холодильнике нашёлся кусочек торта, о котором я забыла. Вот оно, наследство!", "cat": "Необычное и смешное"}, {"id": "happiness-175", "name": "Илья", "text": "Люблю, когда чемодан закрылся без прыжков сверху. Чувствую, что контролирую жизнь.", "cat": "Необычное и смешное"}, {"id": "happiness-176", "name": "Маша", "text": "Иногда счастье — поймать знакомый запах и на секунду снова оказаться в детстве, на летней кухне у бабушки.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-177", "name": "Соня", "text": "Сегодня можно просто быть собой. Без плана, без отчёта, без гонки.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-178", "name": "Нина", "text": "Счастлива от мысли, что многие любимые воспоминания начались с самых обычных дней.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-179", "name": "Аня", "text": "Люблю замечать, как изменился мой дом за годы: вещи те же, а историй в них стало больше.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-180", "name": "Артём", "text": "Кайфую, когда вспоминаю трудную задачу, которая раньше пугала, а теперь кажется посильной.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-181", "name": "Лера", "text": "Счастлива, когда перестаю сравнивать свой день с чужим и замечаю, что в моём тоже было много хорошего.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-182", "name": "Денис", "text": "Мне нравится, что можно ошибиться, переделать и всё равно создать что-то стоящее.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-183", "name": "Вика", "text": "Люблю случайно услышать песню из школьных времён и вспомнить не события, а само ощущение того лета.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-184", "name": "Юля", "text": "Счастлива, когда вижу, как близкие меняются, растут, а между нами остаётся что-то очень родное.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-185", "name": "Илья", "text": "Кайфую от ощущения, что у меня ещё столько мест, где я не был, и дорог, по которым не ходил.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-186", "name": "Маша", "text": "Радуюсь, когда вдруг понимаю: этот обычный вечер, возможно, станет одним из моих тёплых воспоминаний.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-187", "name": "Соня", "text": "Счастье для меня иногда не громкая радость, а спокойствие, в котором ничего не хочется доказывать.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-188", "name": "Нина", "text": "Люблю перечитывать старые заметки и замечать, как много хорошего я тогда не хотела забыть.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-189", "name": "Аня", "text": "Счастлива, когда могу сказать себе: «Сегодня было непросто, но один хороший момент точно случился».", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-190", "name": "Артём", "text": "Сегодня не вышло то, на что я рассчитывал. Но я вдруг поймал себя на мысли: завтра можно попробовать ещё раз, уже с новым пониманием. И почему-то от этого стало спокойнее.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-191", "name": "Лера", "text": "Радуюсь, когда на секунду осознаю, что живу не только ради будущего, но и прямо сейчас.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-192", "name": "Денис", "text": "Счастлив, когда после сложного разговора появляется ясность. Иногда она приятнее, чем идеальный ответ.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-193", "name": "Вика", "text": "Люблю старые фотографии не за идеальные лица, а за смешные детали, которых никто тогда не замечал.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-194", "name": "Юля", "text": "Меня радует, что у нашей семьи есть свои маленькие традиции, которые мы даже не договаривались создавать.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-195", "name": "Илья", "text": "Кайфую, когда в незнакомом месте вдруг чувствую себя спокойно, будто давно здесь бывал.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-196", "name": "Маша", "text": "Счастлива, когда могу просто посмотреть на небо и на минуту перестать мысленно составлять списки.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-197", "name": "Соня", "text": "Люблю вечер, когда день не был выдающимся, но в нём нашлось что-то хорошее, что хочется запомнить.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-198", "name": "Нина", "text": "Вчера мне молча оставили самую вкусную ягоду на тарелке. Никто ничего не сказал, а мне целый вечер было тепло от этого маленького жеста.", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-199", "name": "Аня", "text": "Счастлива, когда вспоминаю себя несколько лет назад и хочется ту себя обнять и сказать: «Ты справилась со многим».", "cat": "Воспоминания, смысл и ощущения"}, {"id": "happiness-200", "name": "Артём", "text": "Кайфую от простого ощущения: я на своём месте, делаю своё дело и рядом есть люди, которых люблю.", "cat": "Воспоминания, смысл и ощущения"}];
