function createStarterBlocksAndStages(todayIso, withGuitarExample) {
  const blocks = [];
  const stages = [];
  const goals = [];

  BASE_8_BLOCKS.forEach(([id, name, icon, color, meaning], idx) => {
    const curId = 'stg_cur_' + id;
    const planId = 'stg_plan_' + id;
    const optId = 'stg_opt_' + id;
    const unkId = 'stg_unk_' + id;
    const lvmgId = 'stg_lvmg_' + id;

    blocks.push({
      id,
      name,
      icon,
      color,
      subtitle: '',
      meaning,
      fact: '',
      priority: idx < 3 ? 3 : 2,
      intensity: 'balanced',
      preset: 'simple', // Понятная простая дорожка по умолчанию, полная (Неизвестное + LVMG) включается в 1 клик!
      secs: { ach: true, fact: true, cur: true, plan: true, opt: true, unk: false, lvmg: false },
      currentStageId: curId,
      routeKnownToLvmg: false,
      order: idx,
      createdAt: todayIso,
      archivedAt: null
    });

    stages.push(
      { id: curId, blockId: id, role: 'step', name: 'Сейчас', description: 'Ближайший спокойный участок изменений', meaning: '', order: 1, status: 'open', completedAt: null, archivedAt: null },
      { id: planId, blockId: id, role: 'step', name: 'Следующий этап', description: '', meaning: '', order: 2, status: 'open', completedAt: null, archivedAt: null },
      { id: optId, blockId: id, role: 'optimal', name: 'Оптимальный ориентир', description: 'Устойчивое состояние «достаточно хорошо»', meaning: '', order: 100, status: 'open', reached: false, completedAt: null, archivedAt: null },
      { id: unkId, blockId: id, role: 'unknown', name: 'Неизвестное', description: 'Участок пути, который прояснится по мере движения', meaning: '', order: 200, status: 'open', completedAt: null, archivedAt: null },
      { id: lvmgId, blockId: id, role: 'lvmg', name: 'Всегда возможно лучшее (LVMG)', description: 'Дальний маяк воображения без превращения мечты в долг', meaning: '', order: 300, status: 'open', completedAt: null, archivedAt: null }
    );
  });

  if (withGuitarExample) {
    // Сквозной авторский пример «Гитара» из архива знаний!
    const gId = 'b_guitar';
    blocks.unshift({
      id: gId,
      name: 'Гитара',
      icon: '🎸',
      color: '#ffd54a',
      subtitle: 'Любимые песни для души',
      meaning: 'Играть любимые песни вечером для себя и друзей — как живой отдых без экранов.',
      fact: 'Инструмент дома и настроен, начинаю почти с нуля, пальцы привыкают к струнам.',
      priority: 3,
      intensity: 'balanced',
      preset: 'full',
      secs: { ach: true, fact: true, cur: true, plan: true, opt: true, unk: true, lvmg: true },
      currentStageId: 'stg_g_chords',
      routeKnownToLvmg: false,
      order: -1,
      createdAt: todayIso,
      archivedAt: null
    });

    stages.push(
      {
        id: 'stg_g_past',
        blockId: gId,
        role: 'step',
        name: 'Выбрать гитару и настроить место дома',
        description: 'Инструмент стоит под рукой на стойке, тюнер скачан.',
        meaning: 'Чтобы между желанием и первой нотой было меньше 10 секунд.',
        order: 0,
        status: 'completed',
        completedAt: todayIso,
        archivedAt: null
      },
      {
        id: 'stg_g_chords',
        blockId: gId,
        role: 'step',
        name: 'Первые аккорды (Am, Dm, E, C)',
        description: 'Спокойно ставить базовые аккорды и менять их без зажатия кисти.',
        meaning: 'Почувствовать живой звук в руках даже за 10 минут вечером.',
        feedMode: 'one',
        order: 1,
        status: 'open',
        completedAt: null,
        archivedAt: null
      },
      {
        id: 'stg_g_song1',
        blockId: gId,
        role: 'step',
        name: 'Первая песня целиком от начала до конца',
        description: 'Сыграть выбранную простую песню ровным боем без остановок.',
        meaning: 'Первая настоящая радость завершённой музыки.',
        order: 2,
        status: 'open',
        completedAt: null,
        archivedAt: null
      },
      {
        id: 'stg_g_rep',
        blockId: gId,
        role: 'step',
        name: 'Небольшой домашний репертуар (5–7 песен)',
        description: 'Песни под разное настроение, которые руки помнят сами.',
        meaning: '',
        order: 3,
        status: 'open',
        completedAt: null,
        archivedAt: null
      },
      {
        id: 'stg_g_opt',
        blockId: gId,
        role: 'optimal',
        name: 'Уверенно играть любимые песни для себя и близких',
        description: 'Свободный вечерний аккомпанемент без напряжения — достаточный, тёплый уровень мастерства.',
        meaning: '',
        order: 100,
        status: 'open',
        reached: false,
        completedAt: null,
        archivedAt: null
      },
      {
        id: 'stg_g_unk',
        blockId: gId,
        role: 'unknown',
        name: 'Импровизация на слух и подбор без табулатур',
        description: 'Пока неизвестно, понадобится ли теория или хватит живой практики с музыкантом.',
        meaning: '',
        order: 200,
        status: 'open',
        completedAt: null,
        archivedAt: null
      },
      {
        id: 'stg_g_lvmg',
        blockId: gId,
        role: 'lvmg',
        name: 'Сочинять свою музыку и свободно играть в живом джеме',
        description: 'Дальний маяк мечты за пределами текущих планов.',
        meaning: '',
        order: 300,
        status: 'open',
        completedAt: null,
        archivedAt: null
      }
    );

    goals.push(
      {
        id: 'goal_g_1',
        blockId: gId,
        stageId: 'stg_g_chords',
        title: 'Чисто менять связку Am — E — Dm в спокойном темпе',
        criterion: '20 переходов подряд без паузы и дребезга струн',
        ifTrigger: 'Вечером сильно устал после работы',
        ifAction: 'Взять гитару ровно на 2 минуты и сделать 5 мягких переходов без требований к себе',
        status: 'active',
        reason: '',
        createdAt: todayIso
      }
    );

    // Также наполним 2 базовых блока в примере короткими живыми данными
    const bBody = blocks.find(b => b.id === 'b_body');
    if (bBody) {
      bBody.fact = 'Утренняя разминка сразу убирает скованность спины.';
      const st = stages.find(s => s.id === bBody.currentStageId);
      if (st) { st.name = 'Бережное движение каждый день и нормальный сон'; st.meaning = 'Чтобы тело давало энергию, а не просило пощады.'; }
      const op = stages.find(s => s.blockId === 'b_body' && s.role === 'optimal');
      if (op) op.name = 'Лёгкое выносливое тело и стабильный сон 7.5 часов';
    }
    const bKnow = blocks.find(b => b.id === 'b_know');
    if (bKnow) {
      bKnow.fact = 'Сильная продуктовая база, книги и живые прототипы.';
      bKnow.preset = 'full';
      bKnow.secs.unk = true; bKnow.secs.lvmg = true;
      bKnow.routeKnownToLvmg = true;
      const st = stages.find(s => s.id === bKnow.currentStageId);
      if (st) { st.name = 'Довести LifeGame 3.0 и главы книги в спокойном ритме'; st.meaning = 'Создавать вещи, которыми хочется пользоваться самому каждый день.'; }
      const op = stages.find(s => s.blockId === 'b_know' && s.role === 'optimal');
      if (op) op.name = '60–90 минут спокойной глубокой работы каждое утро';
      const lv = stages.find(s => s.blockId === 'b_know' && s.role === 'lvmg');
      if (lv) lv.name = 'Живые книги и продукты, которые помогают тысячам людей';
    }
  }

  return { blocks, stages, goals };
}

